```javascript
// ocrFallback.js
import Tesseract from 'tesseract.js';

/**
 * Preprocess image for better OCR accuracy (grayscale + threshold + resize)
 */
async function preprocessImage(imageSource) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const cleanup = () => {
      if (imageSource instanceof File) URL.revokeObjectURL(img.src);
    };

    img.onload = () => {
      try {
        // Limit size for performance
        const MAX_DIM = 1200;
        let width = img.width;
        let height = img.height;
        if (width > MAX_DIM || height > MAX_DIM) {
          const ratio = Math.min(MAX_DIM / width, MAX_DIM / height);
          width *= ratio;
          height *= ratio;
        }

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        canvas.width = width;
        canvas.height = height;

        ctx.drawImage(img, 0, 0, width, height);
        const imageData = ctx.getImageData(0, 0, width, height);
        const data = imageData.data;

        // Grayscale + Binary threshold
        for (let i = 0; i < data.length; i += 4) {
          const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
          const val = avg > 140 ? 255 : 0;
          data[i] = data[i + 1] = data[i + 2] = val;
        }

        ctx.putImageData(imageData, 0, 0);
        resolve(canvas.toDataURL('image/png'));
      } catch (err) {
        reject(err);
      } finally {
        cleanup();
      }
    };

    img.onerror = reject;
    img.src = imageSource instanceof File ? URL.createObjectURL(imageSource) : imageSource;
  });
}

/**
 * Run client-side OCR fallback
 */
export async function runFallbackOCR(imageSource, options = {}) {
  const {
    lang = 'eng',
    logger = () => {},
    preprocess = true,
    timeout = 60000
  } = options;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeout);

  try {
    const processedImage = preprocess ? await preprocessImage(imageSource) : imageSource;

    const result = await Tesseract.recognize(
      processedImage,
      lang,
      {
        logger: (progress) => logger(progress),
        workerParams: {
          corePath: 'https://cdn.jsdelivr.net/npm/tesseract.js@4/dist/tesseract-core.wasm',
          langPath: `https://cdn.jsdelivr.net/npm/tesseract.js@4/dist/${lang}.traineddata.gz`
        }
      },
      { signal: controller.signal }
    );

    clearTimeout(timeoutId);
    return result.data.text;
  } catch (error) {
    clearTimeout(timeoutId);
    if (error.name === 'AbortError') {
      throw new Error('OCR fallback timed out');
    }
    logger({ status: 'error', progress: 0, error: error.message });
    throw new Error(`OCR fallback failed: ${error.message}`);
  }
}

/**
 * Capture frame from camera
 */
export async function captureFromCamera(videoEl, canvasEl) {
  const stream = await navigator.mediaDevices.getUserMedia({
    video: {
      facingMode: 'environment',
      width: { ideal: 1280 },
      height: { ideal: 720 }
    }
  });

  videoEl.srcObject = stream;
  await videoEl.play();

  canvasEl.width = videoEl.videoWidth;
  canvasEl.height = videoEl.videoHeight;
  canvasEl.getContext('2d').drawImage(videoEl, 0, 0);

  stream.getTracks().forEach(track => track.stop());
  return canvasEl.toDataURL('image/jpeg', 0.85);
}
```

