function parseReceiptText(text) {
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  return {
    raw: text,
    lines,
    total: lines.find(l => /total|amount|balance|sum/i.test(l))?.split(/[:\s]+/).pop() || null,
    date: lines.find(l => /\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}/.test(l)) || null,
    merchant: lines[0] || null,
    items: lines.slice(2, -2) // Heuristic: skip header/footer
  };
